mapper.select:
SELECT 
FROM user_kakao_calendar_events
WHERE user_id = #{userId} AND event_id = #{eventId}

mapper.update:
UPDATE user_kakao_calendar_events
SET kakao_event_id = #{kakaoEventId}, sync_status = 'SYNCED', retry_count = 0, last_error = NULL, last_synced_at = NOW()
WHERE user_id = #{userId} AND event_id = #{eventId}

UPDATE user_kakao_calendar_events
SET sync_status = 'FAILED', retry_count = retry_count + 1, last_error = LEFT(#{lastError}, 500)
WHERE user_id = #{userId} AND event_id = #{eventId}

UPDATE user_kakao_calendar_events
SET sync_status = 'DELETED', last_synced_at = NOW()
WHERE user_id = #{userId} AND event_id = #{eventId}
